from abc import ABC, abstractmethod


class AST(ABC):
    @abstractmethod
    def eval(self, env) -> int:
        pass


class BinOp(AST):
    def __init__(self, left: AST, op: str, right: AST):
        self.left = left
        self.op = op
        self.right = right

    def eval(self, env) -> int:
        left = self.left.eval(env)
        right = self.right.eval(env)
        if self.op == "+":
