    def __init__(self, p1: List[str], p2: List[str], payoffs: List[List[Cell]]) -> None:
        """
        p1: list of strategies for player 1
        p2: list of strategies for player 2
        payoffs: list of lists of Cells, representing the payoff matrix

        Example game:
              A     B
