import sys

from flask import Flask, render_template
from flask_flatpages import FlatPages, flatpages
from flask_frozen import Freezer

DEBUG = True
FLATPAGES_AUTO_RELOAD = DEBUG
FLATPAGES_EXTENSION = '.md'
